#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MIN(a, b) ((a) < (b) ? (a) : (b))
#define MAX(a, b) ((a) > (b) ? (a) : (b))

#define MAX_SIZE 500

typedef struct {
    int minRow;
    int maxRow;
    int minCol;
    int maxCol;
} Rect;

Rect *new_Rect() {
    Rect *rect = (Rect *) malloc(sizeof(Rect));
    rect->minRow = INT_MAX;
    rect->maxRow = INT_MIN;
    rect->minCol = INT_MAX;
    rect->maxCol = INT_MIN;
    return rect;
}

void setRow(Rect *rect, int row) {
    rect->minRow = MIN(rect->minRow, row);
    rect->maxRow = MAX(rect->maxRow, row);
}

void setCol(Rect *rect, int col) {
    rect->minCol = MIN(rect->minCol, col);
    rect->maxCol = MAX(rect->maxCol, col);
}

int main() {
    int m, n;
    scanf("%d %d", &m, &n);

    Rect *rects[MAX_SIZE] = {NULL};

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int num;
            scanf("%d", &num);

            if (num > 0) {
                if (rects[num] == NULL) {
                    rects[num] = new_Rect();
                }

                setRow(rects[num], i);
                setCol(rects[num], j);
            }
        }
    }

    int maxArea = 0;
    for (int i = 0; i < MAX_SIZE; i++) {
        Rect *rect = rects[i];

        if (rects[i] != NULL) {
            int area = (rect->maxRow - rect->minRow + 1) * (rect->maxCol - rect->minCol + 1);
            maxArea = MAX(maxArea, area);
        }
    }

    printf("%d\n", maxArea);

    return 0;
}
